export type MediaKey = keyof typeof media;

/**
 * Looks an asset up by key.
 *
 * A miss falls back to an abstract plate rather than to the portrait: a bad
 * key used to resolve to a photograph of a person, which is the one wrong
 * image nobody notices is wrong — it looks deliberate. A plate reads as a
 * plate. In development the miss is also logged, because the only correct
 * number of unresolved keys is zero.
 */
export function asset(key: MediaKey | (string & {})): MediaAsset {
  const found = (media as Record<string, MediaAsset>)[key];
  if (found) return found;

  if (process.env.NODE_ENV !== 'production') {
    console.warn(`[media] no asset for key "${key}" — falling back to home-prism`);
  }

  return media['home-prism'];
}
